package com.boss.industry.controller; import com.boss.common.security.TenantContext; import com.boss.industry.domain.IndustryProfile; import com.boss.industry.repository.IndustryProfileRepository; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/industries") public class IndustryController {private final IndustryProfileRepository r; public IndustryController(IndustryProfileRepository r){this.r=r;} @GetMapping public List<IndustryProfile> list(){return r.findByTenantId(TenantContext.requireTenantId());} @PostMapping public IndustryProfile create(@RequestBody IndustryProfile x){x.setTenantId(TenantContext.requireTenantId());return r.save(x);}}
